<script setup>
import { computed } from 'vue'
import { useProjectStore } from '../stores/project'
import { useEditorStore } from '../stores/editor'
import { THEMES, WIDTH, HEIGHT, elementBounds } from '../lib/model'
import Icon from './Icon.vue'
const emit = defineEmits(['replace'])
const p = useProjectStore(), editor = useEditorStore()
const selected = computed(() => p.elements.find(e => e.id === editor.selection))
const counts = computed(() => { const events = p.days.flatMap(d => d.events); return { broadcast: events.filter(e => e.status === 'broadcast').length, off: events.filter(e => e.status === 'off').length, tbd: p.days.filter(d => !d.events.length).length + events.filter(e => e.status === 'tbd').length } })
function update(key, value) { if (selected.value) p.updateElement(selected.value.id, { [key]: value }) }
function number(key, value) {
  const e = selected.value, n = Number(value)
  if (!e || !Number.isFinite(n)) return
  p.updateElement(e.id, { [key]: n })
}
function align(axis) { const e=selected.value,b=elementBounds(e); p.updateElement(e.id,axis==='x'?{x:(WIDTH-b.width)/2-b.minX}:{y:(HEIGHT-b.height)/2-b.minY}) }
function duplicate() { const id=p.duplicateElement(selected.value.id); if(id) editor.selection=id; else editor.notify('디자인 요소는 100개까지 추가할 수 있어요.','error') }
function remove() { if (selected.value) { p.removeElement(selected.value.id); editor.selection = null } }
</script>
<template>
  <div class="inspector-heading"><span>{{ editor.mode === 'schedule' ? '이번 주 한눈에' : '속성' }}</span><Icon :name="editor.mode === 'schedule' ? 'book' : 'settings'" :size="17" /></div>
  <template v-if="editor.mode === 'schedule'">
    <div class="overview-card"><span class="eyebrow">THIS WEEK</span><strong>{{ p.data.activeWeek.slice(5).replace('-', '.') }} <span>—</span> {{ p.days[6].date.slice(5).replace('-', '.') }}</strong><p>시현의 이야기가 채워질 일주일</p><div class="week-stats"><div><i class="broadcast"></i><b>{{ counts.broadcast }}</b><span>방송</span></div><div><i class="off"></i><b>{{ counts.off }}</b><span>휴방</span></div><div><i class="tbd"></i><b>{{ counts.tbd }}</b><span>미정</span></div></div></div>
    <div class="inspector-section"><div class="section-heading"><h3>현재 디자인</h3><span class="small-tag">16:9</span></div><div class="current-template"><span class="template-dot" :class="p.data.design.templateId"></span><div><strong>{{ THEMES[p.data.design.templateId].name }}</strong><span>1920 × 1080 px</span></div></div><button class="quiet-button wide" @click="editor.setTab('template')">템플릿 살펴보기 <Icon name="right" :size="14" /></button></div>
    <div class="workflow-note"><Icon name="sparkle" :size="19" /><h3>이번 주도, 시현답게.</h3><p>일정을 먼저 채우고,<br>디자인 모드에서 나만의 색을 더하세요.</p><button @click="editor.setTab('layers')">디자인 편집하기 <Icon name="external" :size="14" /></button></div>
  </template>
  <template v-else-if="!selected"><div class="inspector-empty"><div class="empty-icon"><Icon name="pointer" :size="26" /></div><strong>어떤 부분을 바꿔볼까요?</strong><p>캔버스나 레이어에서 요소를 선택하면<br>세부 속성이 여기에 표시돼요.</p></div><div class="keyboard-card"><span class="eyebrow">A LITTLE SHORTCUT</span><p><span>실행 취소</span><kbd>Ctrl Z</kbd></p><p><span>다시 실행</span><kbd>Ctrl Shift Z</kbd></p><p><span>선택 해제</span><kbd>Esc</kbd></p><p><span>요소 삭제</span><kbd>Delete</kbd></p></div></template>
  <template v-else>
    <div class="selected-heading"><span class="element-icon"><Icon :name="selected.type === 'schedule' ? 'calendar' : selected.type" :size="20" /></span><div><strong>{{ selected.name }}</strong><span>{{ { text: '텍스트', image: '이미지', schedule: '일정표 그룹' }[selected.type] }}</span></div></div>
    <div class="element-actions"><button class="quiet-button" @click="update('locked', !selected.locked)"><Icon :name="selected.locked ? 'lock' : 'unlock'" :size="15" />{{ selected.locked ? '잠금 해제' : '잠금' }}</button><button class="quiet-button" @click="update('visible', !selected.visible)"><Icon :name="selected.visible ? 'eye' : 'hidden'" :size="15" />{{ selected.visible ? '표시 중' : '숨김' }}</button></div>
    <div v-if="selected.locked" class="inline-hint"><Icon name="lock" :size="14" /> 잠금을 해제하면 편집할 수 있어요.</div>
    <label class="field layer-name"><span>레이어 이름</span><input aria-label="레이어 이름" maxlength="80" :value="selected.name" @change="update('name', $event.target.value || '이름 없는 요소')" /></label>
    <fieldset :disabled="selected.locked">
      <div class="inspector-section"><h3>위치와 크기</h3><div class="property-grid"><label v-for="key in ['x','y','width','height']" :key="key" class="number-field"><span>{{ { x:'X', y:'Y', width:'W', height:'H' }[key] }}</span><input type="number" :aria-label="key" :value="Math.round(selected[key])" @change="number(key, $event.target.value)" /></label></div><label class="number-field rotation"><Icon name="reset" :size="15" /><input type="number" aria-label="회전" :value="selected.rotation" @change="number('rotation', $event.target.value)" /><span>°</span></label><label v-if="selected.type === 'image'" class="check-field"><input type="checkbox" :checked="selected.keepRatio" @change="update('keepRatio', $event.target.checked)" />이미지 비율 유지</label></div>
      <div v-if="selected.type === 'text'" class="inspector-section"><h3>텍스트</h3><label class="field"><span>내용</span><textarea rows="4" maxlength="2000" aria-label="텍스트 내용" :value="selected.text" @input="update('text', $event.target.value)"></textarea></label><label class="field"><span>폰트</span><select aria-label="폰트" :value="selected.fontFamily" @change="update('fontFamily', $event.target.value)"><option>Malgun Gothic</option><option>Georgia</option><option>Segoe UI</option><option>Arial</option></select></label><div class="field-row"><label class="number-field"><span>크기</span><input type="number" min="6" max="300" aria-label="글자 크기" :value="selected.fontSize" @change="update('fontSize', Math.max(6, Math.min(300, Number($event.target.value) || 36)))" /></label><button class="quiet-button" :class="{ active: selected.bold }" title="굵게" :aria-pressed="selected.bold" @click="update('bold', !selected.bold)"><Icon name="bold" :size="16" /></button></div><div class="align-controls"><button v-for="a in ['left','center','right']" :key="a" class="quiet-button" :class="{ active: selected.align === a }" :aria-label="`텍스트 ${a} 정렬`" @click="update('align', a)"><Icon :name="`align${a[0].toUpperCase()}${a.slice(1)}`" :size="17" /></button></div><label class="color-field"><input aria-label="글자 색상" type="color" :value="selected.fill" @input="update('fill', $event.target.value)" /><span>{{ selected.fill.toUpperCase() }}</span><span>100%</span></label></div>
      <div v-if="selected.type==='image'" class="inspector-section"><h3>이미지 프레임</h3><label class="field"><span>맞춤 방식</span><select aria-label="이미지 맞춤 방식" :value="selected.cropMode||'contain'" @change="update('cropMode',$event.target.value)"><option value="contain">원본 전체 표시</option><option value="cover">프레임 채우기 · 자르기</option></select></label><template v-if="selected.cropMode==='cover'"><label class="field crop-control"><span>가로 자르기 위치</span><input aria-label="가로 자르기 위치" type="range" min="0" max="1" step=".01" :value="selected.cropX??.5" @input="update('cropX',Number($event.target.value))" /></label><label class="field crop-control"><span>세로 자르기 위치</span><input aria-label="세로 자르기 위치" type="range" min="0" max="1" step=".01" :value="selected.cropY??.5" @input="update('cropY',Number($event.target.value))" /></label></template><p class="muted-copy">비율 유지를 해제하면 프레임을 다른 비율로 만들 수 있어요. 원본 파일은 그대로 보관해요.</p><button class="quiet-button wide" @click="emit('replace',selected.id)">이미지 교체<Icon name="image" :size="14" /></button></div>
      <div v-if="selected.type === 'schedule'" class="inspector-section"><h3>연결된 일정</h3><p class="muted-copy">일정표의 제목과 시간은 일정 편집에서 관리해요. 크기와 위치는 자유롭게 조절할 수 있어요.</p><button class="quiet-button wide" @click="editor.setTab('schedule')">일정 수정하기 <Icon name="right" :size="14" /></button></div>
      <div class="inspector-section"><h3>정렬과 복제</h3><div class="element-actions"><button class="quiet-button" @click="align('x')">가로 중앙</button><button class="quiet-button" @click="align('y')">세로 중앙</button></div><button class="quiet-button wide property-action" @click="p.fitElement(selected.id)">캔버스 안에 맞춤<Icon name="fit" :size="14" /></button><button class="quiet-button wide property-action" @click="duplicate">요소 복제<kbd>Ctrl D</kbd></button></div>
      <div class="inspector-section"><h3>레이어 순서</h3><div class="element-actions"><button class="quiet-button" :disabled="p.elements.at(-1)?.id === selected.id" @click="p.reorder(selected.id, 1)"><Icon name="up" :size="15" />앞으로</button><button class="quiet-button" :disabled="p.elements[0]?.id === selected.id" @click="p.reorder(selected.id, -1)"><Icon name="lower" :size="15" />뒤로</button></div><button class="delete-element" @click="remove()"><Icon name="trash" :size="15" />요소 삭제 <kbd>Del</kbd></button></div>
    </fieldset>
  </template>
</template>
